/**
 * Backfill grid thumbnails for image assets.
 *
 * The assets grid used to point every tile at the full-resolution R2 original, so opening
 * the tab downloaded tens of MB of 2.5 MB PNGs to paint a 200px square. This writes a 480px
 * JPEG into `metadata.thumbnailUrl`, which the grid prefers when present. Video assets are
 * skipped (their posters are generated by /api/video/thumbnail).
 *
 *   npx esbuild scripts/backfill-image-thumbnails.ts --bundle --platform=node \
 *     --format=esm --packages=external --outfile=.tmp-thumbs.mjs
 *   node .tmp-thumbs.mjs --tenant <uuid> [--all] [--dry-run] [--width 480]
 */
import '../lib/env-local';
import { createClient } from '@supabase/supabase-js';
import sharp from 'sharp';
import { uploadBufferToR2 } from '../lib/agent/sandbox';

const args = process.argv.slice(2);
const flag = (name: string) => args.includes(`--${name}`);
const value = (name: string, fallback?: string) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};

const TENANT = value('tenant');
const ALL = flag('all');
const DRY = flag('dry-run');
const WIDTH = Number(value('width', '480'));

if (!TENANT && !ALL) {
  console.error('Need --tenant <uuid> or --all');
  process.exit(1);
}

const sb = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, {
  auth: { persistSession: false },
});

const PAGE = 500;

async function thumbnailsForTenant(userId: string) {
  let from = 0;
  let scanned = 0;
  let converted = 0;
  let savedBytes = 0;
  let srcBytes = 0;

  for (;;) {
    const { data, error } = await sb
      .from('assets')
      .select('id, url, type, metadata')
      .eq('user_id', userId)
      .eq('type', 'image')
      .order('created_at', { ascending: false })
      .range(from, from + PAGE - 1);
    if (error) throw new Error(error.message);
    const rows = data || [];
    if (!rows.length) break;
    from += rows.length;

    for (const row of rows) {
      scanned++;
      if (!row.url || !row.url.startsWith('http')) continue;
      if (row.metadata?.thumbnailUrl) continue; // already done (idempotent)

      try {
        const res = await fetch(row.url);
        if (!res.ok) {
          console.log(`  FAIL ${row.id.slice(0, 8)} HTTP ${res.status}`);
          continue;
        }
        const original = Buffer.from(await res.arrayBuffer());
        const thumb = await sharp(original)
          .rotate()
          .resize({ width: WIDTH, withoutEnlargement: true })
          .jpeg({ quality: 72, progressive: true, mozjpeg: true })
          .toBuffer();

        if (DRY) {
          console.log(`  would convert ${row.id.slice(0, 8)} ${(original.length / 1024).toFixed(0)} KB -> ${(thumb.length / 1024).toFixed(0)} KB`);
          srcBytes += original.length;
          savedBytes += Math.max(0, original.length - thumb.length);
          converted++;
          continue;
        }

        const thumbUrl = await uploadBufferToR2(thumb, `grid-${row.id.slice(0, 12)}.jpg`, userId);
        const { error: upErr } = await sb
          .from('assets')
          .update({ metadata: { ...(row.metadata || {}), thumbnailUrl: thumbUrl } })
          .eq('id', row.id);
        if (upErr) {
          console.log(`  FAIL ${row.id.slice(0, 8)} db: ${upErr.message}`);
          continue;
        }
        converted++;
        srcBytes += original.length;
        savedBytes += Math.max(0, original.length - thumb.length);
        console.log(`  ok ${row.id.slice(0, 8)} ${(original.length / 1024).toFixed(0)} KB -> ${(thumb.length / 1024).toFixed(0)} KB`);
      } catch (e: any) {
        console.log(`  FAIL ${row.id.slice(0, 8)} ${e?.message}`);
      }
    }
  }

  return { userId, scanned, converted, savedMB: savedBytes / 1048576, srcMB: srcBytes / 1048576 };
}

const tenants: string[] = [];
if (ALL) {
  const { data } = await sb.from('assets').select('user_id').eq('type', 'image').limit(5000);
  for (const r of data || []) if (r.user_id && !tenants.includes(r.user_id)) tenants.push(r.user_id);
} else if (TENANT) {
  tenants.push(TENANT);
}

console.log(`tenants: ${tenants.length} | width ${WIDTH}px${DRY ? ' | DRY RUN' : ''}`);
for (const t of tenants) {
  const r = await thumbnailsForTenant(t);
  console.log(`\n${r.userId}: scanned ${r.scanned}, converted ${r.converted}, ${r.srcMB.toFixed(1)} MB -> saved ${r.savedMB.toFixed(1)} MB`);
}
